import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
} from "remotion";
import React from "react";

export const fps = 25;
export const durationInFrames = 750;

const tc = (seconds: number) => Math.round(seconds * 25);

const FadeIn: React.FC<{
  delay: number;
  children: React.ReactNode;
  direction?: "up" | "down";
}> = ({ delay, children, direction = "up" }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, delay, config: { damping: 170, stiffness: 80 } });
  const yShift = direction === "up" ? 60 : -60;
  return (
    <div
      style={{
        opacity: p,
        transform: `translateY(${interpolate(p, [0, 1], [yShift, 0])}px)`,
      }}
    >
      {children}
    </div>
  );
};

const SpringIn: React.FC<{
  delay: number;
  children: React.ReactNode;
  direction?: "up" | "left" | "right" | "scale";
}> = ({ delay, children, direction = "up" }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, delay, config: { damping: 180, stiffness: 80 } });
  let transform = "";
  if (direction === "up") transform = `translateY(${interpolate(p, [0, 1], [80, 0])}px)`;
  if (direction === "left") transform = `translateX(${interpolate(p, [0, 1], [-120, 0])}px)`;
  if (direction === "right") transform = `translateX(${interpolate(p, [0, 1], [120, 0])}px)`;
  if (direction === "scale") transform = `scale(${interpolate(p, [0, 1], [0.7, 1])})`;
  return (
    <div style={{ opacity: p, transform }}>
      {children}
    </div>
  );
};

